//go:build ignore

// Gen_arith writes the generated files of package bid: zNAME64.go and
// zNAME128.go from each template NAME_tmpl.go, zpow10.go, the powers of
// ten that the coefficient vocabulary indexes, and zdpd.go, the declet
// tables of the DPD conversions. It is run by the
// go:generate directive in arith.go from the package directory, and by
// TestGenerated with -out set to a scratch directory to check that the
// committed files are current.
//
// The substitution is the width suffix rule of "Width parameterisation" in
// the package documentation and nothing more: in the template, every
// identifier ending in a capital W has that W replaced by the width. The
// generator then formats the result, so the template need not be formatted
// for its output to be.
package main

import (
	"flag"
	"fmt"
	"go/format"
	"log"
	"math/big"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const (
	templateSuffix = "_tmpl.go"
	buildTag       = "//go:build ignore\n"
	generatedFmt   = "// Code generated by gen_arith.go from %s; DO NOT EDIT.\n"
)

// widthIdent matches an identifier ending in a capital W, in code and in
// comments alike. The letters before the W make the identifier at least two
// characters long, so a lone W (as in a comment about "the W suffix") is
// left alone.
var widthIdent = regexp.MustCompile(`\b[A-Za-z_][A-Za-z0-9_]*W\b`)

func main() {
	log.SetFlags(0)
	log.SetPrefix("gen_arith: ")
	out := flag.String("out", ".", "directory to write the generated files to")
	flag.Parse()

	templates, err := filepath.Glob("*" + templateSuffix)
	if err != nil {
		log.Fatal(err)
	}
	if len(templates) == 0 {
		log.Fatalf("no *%s files in the current directory", templateSuffix)
	}
	for _, name := range templates {
		tmpl, err := os.ReadFile(name)
		if err != nil {
			log.Fatal(err)
		}
		// Everything from the build constraint to the package clause is
		// commentary on the template and does not belong to the generated
		// file: the constraint goes, and the generated-code marker takes
		// its place.
		text := string(tmpl)
		tag := strings.Index(text, buildTag)
		pkg := strings.Index(text, "\npackage bid\n")
		if tag < 0 || pkg < tag {
			log.Fatalf("%s lacks %q before its package clause", name, strings.TrimSpace(buildTag))
		}
		body := text[:tag] + fmt.Sprintf(generatedFmt, name) + text[pkg:]

		base := strings.TrimSuffix(name, templateSuffix)
		for _, width := range []string{"64", "128"} {
			src := widthIdent.ReplaceAllStringFunc(body, func(id string) string {
				return strings.TrimSuffix(id, "W") + width
			})
			write(*out, "z"+base+width+".go", src)
		}
	}
	write(*out, "zpow10.go", pow10Source())
	write(*out, "zdpd.go", dpdSource())
}

// write formats src and writes it to dir/name.
func write(dir, name, src string) {
	b, err := format.Source([]byte(src))
	if err != nil {
		log.Fatalf("%s: %v", name, err)
	}
	if err := os.WriteFile(filepath.Join(dir, name), b, 0o666); err != nil {
		log.Fatal(err)
	}
}

// pow10Source returns the source of zpow10.go: the powers of ten that fit
// 64, 128 and 256 bits, as the tables indexed by the coefficient
// vocabulary. A table is never larger than the width allows, so an index
// beyond it is a bug that panics rather than a wrong power.
func pow10Source() string {
	var sb strings.Builder
	sb.WriteString(`// Copyright 2026 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

`)
	fmt.Fprintf(&sb, generatedFmt, "the table in gen_arith.go")
	sb.WriteString(`
package bid

// The powers of ten below 2^64, 2^128 and 2^256, indexed by the exponent.
// They are initialised statically: there is no run-time work, which keeps
// the package usable from the runtime.
`)
	mask := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 64), big.NewInt(1))
	words := func(v *big.Int) [4]uint64 { // least significant first
		var w [4]uint64
		for i := range w {
			w[i] = new(big.Int).And(new(big.Int).Rsh(v, uint(64*i)), mask).Uint64()
		}
		return w
	}
	table := func(name, typ string, bits uint, entry func(v *big.Int) string) {
		limit := new(big.Int).Lsh(big.NewInt(1), bits)
		var vals []*big.Int
		for p := big.NewInt(1); p.Cmp(limit) < 0; p = new(big.Int).Mul(p, big.NewInt(10)) {
			vals = append(vals, p)
		}
		fmt.Fprintf(&sb, "\n// %s[k] is 10^k, for k in [0, %d].\nvar %s = [%d]%s{\n", name, len(vals)-1, name, len(vals), typ)
		for _, v := range vals {
			sb.WriteString("\t" + entry(v) + ",\n")
		}
		sb.WriteString("}\n")
	}
	table("pow10tab64", "uint64", 64, func(v *big.Int) string { return v.String() })
	table("pow10tab128", "Uint128", 128, func(v *big.Int) string {
		w := words(v)
		return fmt.Sprintf("{Hi: %#016x, Lo: %#016x}", w[1], w[0])
	})
	table("pow10tab256", "Uint256", 256, func(v *big.Int) string {
		w := words(v)
		return fmt.Sprintf("{Hi: Uint128{Hi: %#016x, Lo: %#016x}, Lo: Uint128{Hi: %#016x, Lo: %#016x}}", w[3], w[2], w[1], w[0])
	})
	return sb.String()
}

// dpdSource returns the source of zdpd.go: the tables between three-digit
// integers and the 10-bit declets of the densely packed decimal encoding.
// The declets come from the encoding table of IEEE 754-2008 clause 3.5.2
// (Table 3.4), written below as bit operations on the BCD digits; decoding
// follows the decoding table (Table 3.3), which maps the 24 redundant
// declets to the same digits as their canonical twins.
func dpdSource() string {
	var sb strings.Builder
	sb.WriteString(`// Copyright 2026 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

`)
	fmt.Fprintf(&sb, generatedFmt, "the declet tables in gen_arith.go")
	sb.WriteString(`
package bid

// bin2dpd[n] is the canonical declet of the three digits of n, for n in
// [0, 999], and dpd2bin[d] is the integer the declet d encodes, for every d
// in [0, 1023]. They are initialised statically, like the powers of ten.
`)
	row := func(i int) string { // eight entries to a line
		if i%8 == 0 {
			return "\n\t"
		}
		return " "
	}
	sb.WriteString("var bin2dpd = [1000]uint16{")
	for n := 0; n < 1000; n++ {
		fmt.Fprintf(&sb, "%s%#03x,", row(n), encodeDeclet(n))
	}
	sb.WriteString("\n}\n\nvar dpd2bin = [1024]uint16{")
	for d := 0; d < 1024; d++ {
		fmt.Fprintf(&sb, "%s%d,", row(d), decodeDeclet(d))
	}
	sb.WriteString("\n}\n")
	return sb.String()
}

// encodeDeclet returns the declet pqrstuvwxy of the BCD digits abcd efgh
// ijkm of n (Table 3.4, indexed by the indicator bits a, e and i).
func encodeDeclet(n int) int {
	d1, d2, d3 := n/100, n/10%10, n%10
	bit := func(d, k int) int { return d >> k & 1 }
	a, b, c, d := bit(d1, 3), bit(d1, 2), bit(d1, 1), bit(d1, 0)
	e, f, g, h := bit(d2, 3), bit(d2, 2), bit(d2, 1), bit(d2, 0)
	i, j, k, m := bit(d3, 3), bit(d3, 2), bit(d3, 1), bit(d3, 0)
	var p, q, r, s, t, u, v, w, x, y int
	switch a<<2 | e<<1 | i {
	case 0b000:
		p, q, r, s, t, u, v, w, x, y = b, c, d, f, g, h, 0, j, k, m
	case 0b001:
		p, q, r, s, t, u, v, w, x, y = b, c, d, f, g, h, 1, 0, 0, m
	case 0b010:
		p, q, r, s, t, u, v, w, x, y = b, c, d, j, k, h, 1, 0, 1, m
	case 0b011:
		p, q, r, s, t, u, v, w, x, y = b, c, d, 1, 0, h, 1, 1, 1, m
	case 0b100:
		p, q, r, s, t, u, v, w, x, y = j, k, d, f, g, h, 1, 1, 0, m
	case 0b101:
		p, q, r, s, t, u, v, w, x, y = f, g, d, 0, 1, h, 1, 1, 1, m
	case 0b110:
		p, q, r, s, t, u, v, w, x, y = j, k, d, 0, 0, h, 1, 1, 1, m
	case 0b111:
		p, q, r, s, t, u, v, w, x, y = 0, 0, d, 1, 1, h, 1, 1, 1, m
	}
	return p<<9 | q<<8 | r<<7 | s<<6 | t<<5 | u<<4 | v<<3 | w<<2 | x<<1 | y
}

// decodeDeclet returns the integer the declet pqrstuvwxy encodes (Table
// 3.3, indexed by v, then w and x, then s and t).
func decodeDeclet(dpd int) int {
	bit := func(k int) int { return dpd >> k & 1 }
	p, q, r, s, t, u, v, w, x, y := bit(9), bit(8), bit(7), bit(6), bit(5), bit(4), bit(3), bit(2), bit(1), bit(0)
	three := func(h, m, l int) int { return h<<2 | m<<1 | l }
	var d1, d2, d3 int
	switch {
	case v == 0:
		d1, d2, d3 = three(p, q, r), three(s, t, u), three(w, x, y)
	case w == 0 && x == 0:
		d1, d2, d3 = three(p, q, r), three(s, t, u), 8+y
	case w == 0 && x == 1:
		d1, d2, d3 = three(p, q, r), 8+u, three(s, t, y)
	case w == 1 && x == 0:
		d1, d2, d3 = 8+r, three(s, t, u), three(p, q, y)
	case s == 0 && t == 0:
		d1, d2, d3 = 8+r, 8+u, three(p, q, y)
	case s == 0 && t == 1:
		d1, d2, d3 = 8+r, three(p, q, u), 8+y
	case s == 1 && t == 0:
		d1, d2, d3 = three(p, q, r), 8+u, 8+y
	default:
		d1, d2, d3 = 8+r, 8+u, 8+y
	}
	return d1*100 + d2*10 + d3
}
